const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7'); // You must include this line

async function runAnalysis() {
  try {
    // Helpers
    const getInfo = (obj) => new Promise((resolve, reject) => obj.evaluate(resolve, reject));

    // 1. Geometry & Time Definitions
    const region = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
      .filter(ee.Filter.eq('country_na', 'Thailand')).geometry();
    const scale = 3000;
    const start2016 = '2016-04-01';
    const end2016 = '2016-05-01';
    const startBase = '2001-04-01';
    const endBase = '2010-05-01';

    // 2. Masking function for MODIS LST Day
    function maskMODISLST(img) {
      const qc = img.select('QC_Day');
      const goodQuality = qc.bitwiseAnd(3).eq(0);            // bits 0-1 == 0
      const errBits = qc.rightShift(6).bitwiseAnd(3);        // bits 6-7
      const errOk = errBits.lte(1);                          // <= 2K error
      const mask = goodQuality.and(errOk);
      const lstC = img.select('LST_Day_1km')
        .updateMask(mask)
        .multiply(0.02).subtract(273.15)
        .rename('LST_C');
      return lstC.copyProperties(img, ['system:time_start']);
    }

    function buildCol(product, s, e) {
      return ee.ImageCollection(product)
        .filterDate(s, e)
        .filterBounds(region)
        .map(maskMODISLST)
        .select('LST_C');
    }

    async function getColWithFallback(s, e) {
      let product = 'MODIS/061/MOD11A2';
      let col = buildCol(product, s, e);
      let size = await getInfo(col.size());
      if (!size || size === 0) {
        product = 'MODIS/061/MOD11A1';
        col = buildCol(product, s, e);
        size = await getInfo(col.size());
      }
      return { col, product, size: size || 0 };
    }

    const totalPx = await getInfo(
      ee.Image(1).rename('c').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e12
      }).get('c')
    );

    // Acquire collections (with fallback)
    const { col: col2016, product: prod2016, size: size2016 } = await getColWithFallback(start2016, end2016);
    const { col: colBase, product: prodBase, size: sizeBase } = await getColWithFallback(startBase, endBase);

    if (size2016 === 0 || sizeBase === 0) {
      console.log(`2016 Images: ${size2016}, Baseline Images: ${sizeBase}`);
      console.log('Empty collection for one or both periods after fallback.');
      console.log('C1');
      return;
    }

    // 3. Processing and stats
    const img2016 = col2016.mean();
    const imgBase = colBase.mean();

    const dict = ee.Dictionary({
      size2016: size2016,
      sizeBase: sizeBase,
      prod2016: prod2016,
      prodBase: prodBase,
      valid2016: img2016.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e12
      }).get('LST_C'),
      validBase: imgBase.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e12
      }).get('LST_C'),
      mean2016: img2016.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: region,
        scale: scale,
        maxPixels: 1e12
      }).get('LST_C'),
      meanBase: imgBase.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: region,
        scale: scale,
        maxPixels: 1e12
      }).get('LST_C'),
      totalPx: totalPx
    });

    const stats = await getInfo(dict);
    const v2016 = stats.valid2016 || 0;
    const vBase = stats.validBase || 0;

    // Handle No Valid Pixels
    if (v2016 === 0 || vBase === 0) {
      console.log(`2016 Images: ${stats.size2016}, Baseline Images: ${stats.sizeBase}`);
      console.log(`Valid px 2016: ${v2016}/${stats.totalPx}, Valid px baseline: ${vBase}/${stats.totalPx}`);
      console.log('C2');
      return;
    }

    const m2016 = stats.mean2016;
    const mBase = stats.meanBase;

    // Validate computations
    const invalid = (x) => (x === null || x === undefined || isNaN(x) || x < -50 || x > 70);
    if (invalid(m2016) || invalid(mBase)) {
      console.log(`Mean LST check failed. 2016: ${m2016}, Baseline: ${mBase}`);
      console.log('C3');
      return;
    }

    const diff = m2016 - mBase;
    const cov2016 = (v2016 / stats.totalPx) * 100.0;
    const covBase = (vBase / stats.totalPx) * 100.0;

    // 4. Evidence (concise)
    console.log(`Products used => 2016: ${stats.prod2016}, Baseline: ${stats.prodBase}`);
    console.log(`April 2016 images: ${stats.size2016}`);
    console.log(`Apr 2001-2010 images: ${stats.sizeBase}`);
    console.log(`2016 valid px: ${v2016}/${stats.totalPx} (${cov2016.toFixed(1)}%)`);
    console.log(`Baseline valid px: ${vBase}/${stats.totalPx} (${covBase.toFixed(1)}%)`);
    console.log(`Mean LST 2016 (C): ${m2016.toFixed(2)}`);
    console.log(`Mean LST 2001-10 Apr (C): ${mBase.toFixed(2)}`);
    console.log(`Diff 2016 - baseline (C): ${diff.toFixed(2)}`);

    // 5. Final Answer
    if (diff > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
